package android.os;public class Bundle{public Bundle(){}public Bundle(Bundle b){data.putAll(b.data);}public void remove(String k){data.remove(k);}public final java.util.Map<String,Object> data=new java.util.HashMap<>();public void putString(String k,String v){data.put(k,v);}public String getString(String k){return data.get(k) instanceof String?(String)data.get(k):null;}public String getString(String k,String d){String v=getString(k);return v==null?d:v;}public void putInt(String k,int v){data.put(k,v);}public int getInt(String k,int d){return data.get(k) instanceof Integer?(Integer)data.get(k):d;}}
